import numpy as np

def simulate(doc, scope, inputs, params, start=None, horizon=None) -> list:
    """
    A forward model of the physics process recorded in the scope.
    Objects move at constant velocity and collide elastically.
    All objects are treated as having equal mass.
    """
    # 1. Time boundaries
    # recorded_end(doc, scope) is a provided helper
    rec_end_val = recorded_end(doc, scope)
    if horizon is None:
        horizon = rec_end_val if rec_end_val is not None else 127.0
    if start is None:
        start = 0.0

    # 2. State initialization
    # state[eid] stores current physics properties of an entity.
    state = {}  # eid -> {'x', 'y', 'vx', 'vy', 'exists': True}
    sorted_inputs = sorted(inputs, key=lambda x: x["time"])
    outcomes_found = []

    t = 0.0
    input_idx = 0
    dt = 0.1  # Simulation time step (frames are integers, but we use smaller dt for precision)
    collision_threshold = 1.2
    exit_threshold = 15.0
    last_collision_time = {}  # (eid1, eid2) -> time to prevent sticking

    # 3. Simulation loop from t=0 to horizon
    while t <= horizon:
        # Handle arrival events (exogenous inputs)
        while input_idx < len(sorted_inputs) and sorted_inputs[input_idx]["time"] <= t:
            inp = sorted_inputs[input_idx]
            for eid in inp["entities"]:
                f = inp["fields"]
                state[eid] = {
                    'x': f.get('x', 0.0),
                    'y': f.get('y', 0.0),
                    'vx': f.get('vx', 0.0),
                    'vy': f.get('vy', 0.0),
                    'exists': True
                }
            input_idx += 1

        # Motion update: Update positions of all existing objects
        for eid, s in state.items():
            if s['exists']:
                s['x'] += s['vx'] * dt
                s['y'] += s['vy'] * dt

        # Collision check: apply equal-mass elastic collision rules
        active_eids = [eid for eid, s in state.items() if s['exists']]
        for i in range(len(active_eids)):
            for j in range(i + 1, len(active_eids)):
                eid1, eid2 = active_eids[i], active_eids[j]
                p1 = np.array([state[eid1]['x'], state[eid1]['y']])
                p2 = np.array([state[eid2]['x'], state[eid2]['y']])

                dist = np.linalg.norm(p1 - p2)
                if dist < collision_threshold:
                    pair = tuple(sorted([eid1, eid2]))
                    # cooldown to prevent multiple collisions in one pass (sticking)
                    if last_collision_time.get(pair, -100) < t - 2.0:
                        v1 = np.array([state[eid1]['vx'], state[eid1]['vy']])
                        v2 = np.array([state[eid2]['vx'], state[eid2]['vy']])
                        n = p1 - p2
                        n_len = np.linalg.norm(n)
                        if n_len > 0:
                            n = n / n_len
                            v_rel = v1 - v2
                            v_rel_n = np.dot(v_rel, n)
                            if v_rel_n < 0:  # Objects must be moving towards each other
                                # Equal mass elastic collision formula:
                                # v1_after = v1_before - proj_n(v_rel)
                                # v2_after = v2_before + proj_n(v_rel)
                                dv = v_rel_n * n
                                state[eid1]['vx'] -= dv[0]
                                state[eid1]['vy'] -= dv[1]
                                state[eid2]['vx'] += dv[0]
                                state[eid2]['vy'] += dv[1]
                                last_collision_time[pair] = t
                                if t > start:
                                    outcomes_found.append({
                                        "time": float(round(t)),
                                        "kind": "collision",
                                        "entities": [eid1, eid2],
                                        "value": None,
                                        "src": None
                                    })

        # Exit check: remove objects leaving the simulation boundary
        for eid in active_eids:
            s = state[eid]
            if abs(s['x']) > exit_threshold or abs(s['y']) > exit_threshold:
                s['exists'] = False
                if t > start:
                    outcomes_found.append({
                        "time": float(round(t)),
                        "kind": "exit",
                        "entities": [eid],
                        "value": None,
                        "src": None
                    })
        t += dt

    return outcomes_found

