        for eid, s in state.items():
            if s['exists']:
                s['x'] += s['vx'] * dt
                s['y'] += s['vy'] * dt

        # Check for collisions between existing objects
        active_eids = [eid for eid, s in state.items() if s['exists']]
        for i in range(len(active_eids)):
            for j in range(i + 1, len(active_eids)):
                eid1, eid2 = active_eids[i], active_eids[j]
                p1 = np.array([state[eid1]['x'], state[eid1]['y']])
                p2 = np.array([state[eid2]['x'], state[eid2]['y']])

