    state = {}  # eid -> {'x', 'y', 'vx', 'vy', 'exists': True}
    sorted_inputs = sorted(inputs, key=lambda x: x["time"])
    outcomes_found = []

    t = 0.0
    input_idx = 0
    dt = 0.1  # Time step for simulation

    # Based on observed data, the collision distance is typically around 0.6 to 1.5.
    # We use a threshold that captures these, but since the model was missing collisions,
    # we increase it slightly. 2.5 is a safer upper bound to ensure detections.
    collision_threshold = 2.5

    # Exit threshold: determined from exit records to be roughly +/- 15 to 20.
    # We use a slightly larger threshold to ensure objects only exit when they are clearly gone.
    exit_threshold = 20.0

    # Cooldown to prevent the same pair from colliding every single time step (sticking)
    last_collision_time = {}  # (eid1, eid2) -> time

    # 3. Simulation Loop
    # Run from t=0 to horizon to correctly propagate states, 
    # but only collect outcomes occurring after the 'start' time.
    while t <= horizon:
        # Handle object arrivals
        while input_idx < len(sorted_inputs) and sorted_inputs[input_idx]["time"] <= t:
            inp = sorted_inputs[input_idx]
            for eid in inp["entities"]:
                f = inp["fields"]
                state[eid] = {
                    'x': f.get('x', 0.0),
                    'y': f.get('y', 0.0),
                    'vx': f.get('vx', 0.0),
                    'vy': f.get('vy', 0.0),
                    'exists': True
                }
            input_idx += 1

        # Update positions based on current velocities (constant velocity motion)
        for eid, s in state.items():
            if s['exists']:
                s['x'] += s['vx'] * dt
                s['y'] += s['vy'] * dt

        # Check for collisions between existing objects
        active_eids = [eid for eid, s in state.items() if s['exists']]
        for i in range(len(active_eids)):
            for j in range(i + 1, len(active_eids)):
                eid1, eid2 = active_eids[i], active_eids[j]
                p1 = np.array([state[eid1]['x'], state[eid1]['y']])
                p2 = np.array([state[eid2]['x'], state[eid2]['y']])

                dist = np.linalg.norm(p1 - p2)
                if dist < collision_threshold:
                    pair = tuple(sorted([eid1, eid2]))
                    # Prevent multiple collisions for the same pair in a very short window
                    if last_collision_time.get(pair, -100) < t - 2.0:
                        v1 = np.array([state[eid1]['vx'], state[eid1]['vy']])
                        v2 = np.array([state[eid2]['vx'], state[eid2]['vy']])
                        n = p1 - p2
                        n_len = np.linalg.norm(n)
                        if n_len > 0:
                            n = n / n_len
                            v_rel = v1 - v2
                            v_rel_n = np.dot(v_rel, n)

                            # Collide only if they are moving towards each other
                            if v_rel_n < 0:
                                # Equal mass elastic collision:
                                # v1_new = v1 - proj_n(v_rel)
                                # v2_new = v2 + proj_n(v_rel)
                                dv = v_rel_n * n
                                state[eid1]['vx'] -= dv[0]
                                state[eid1]['vy'] -= dv[1]
                                state[eid2]['vx'] += dv[0]
                                state[eid2]['vy'] += dv[1]
                                last_collision_time[pair] = t

                                if t > start:
                                    outcomes_found.append({
                                        "time": float(round(t)),
                                        "kind": "collision",
                                        "entities": [eid1, eid2],
                                        "value": None,
                                        "src": None
                                    })

        # Check for exits (objects leaving the simulated floor area)
        for eid in active_eids:
            s = state[eid]
            if abs(s['x']) > exit_threshold or abs(s['y']) > exit_threshold:
                s['exists'] = False
                if t > start:
                    outcomes_found.append({
                        "time": float(round(t)),
                        "kind": "exit",
                        "entities": [eid],
                        "value": None,
                        "src": None
                    })

        t += dt

    return outcomes_found

