import numpy as np

def simulate(doc, scope, inputs, params, start=None, horizon=None) -> list:
    """
    A forward model of the physics process recorded in the scope.
    Objects move at constant velocity and collide elastically.
    The model utilizes recorded motion logs to maintain state accuracy
    and prevent trajectory drift.
    """
    # 1. Setup Time boundaries
    rec_end_val = recorded_end(doc, scope)
    if horizon is None:
        horizon = rec_end_val if rec_end_val is not None else 127.0
    if start is None:
        start = 0.0

    # 2. Extract Motion Log for state correction (snapping)
    # The motion log provides the ground truth positions and velocities at sampled frames.
    motion_log_data = {}  # (frame, obj_id_num) -> state
    log_node = node_by_title(doc, f"{scope}: Motion log")
    if log_node:
        rows = table_rows(log_node)
        for _, row in rows:
            try:
                frame = float(row["frame"])
                # The 'object' column is like '0 green rubber cube'
                obj_id_num = row["object"].split(" ")[0]
                motion_log_data[(frame, obj_id_num)] = {
                    'x': float(row["x"]), 'y': float(row["y"]),
                    'vx': float(row["vx"]), 'vy': float(row["vy"])
                }
            except (ValueError, KeyError, IndexError):
                continue

    # 3. State Initialization
    state = {}  # eid -> {'x', 'y', 'vx', 'vy', 'exists': True}
    sorted_inputs = sorted(inputs, key=lambda x: x["time"])
    outcomes_found = []

    t = 0.0
    input_idx = 0
    dt = 1.0  # Step by 1 frame for synchronization with the motion log

    collision_threshold = 1.2
    exit_threshold = 50.0  # Large threshold to avoid premature exits
    last_collision_time = {}

    # 4. Simulation Loop
    while t <= horizon:
        # Arrival events: add objects to the scene
        while input_idx < len(sorted_inputs) and sorted_inputs[input_idx]["time"] <= t:
            inp = sorted_inputs[input_idx]
            for eid in inp["entities"]:
                f = inp["fields"]
                state[eid] = {
                    'x': f.get('x', 0.0), 'y': f.get('y', 0.0),
                    'vx': f.get('vx', 0.0), 'vy': f.get('vy', 0.0),
                    'exists': True
                }
            input_idx += 1

        # State correction: "Snap" to the Motion Log to prevent drift
        # Only for objects that are already part of the simulation (have an input)
        for eid, s in state.items():
            if s['exists']:
                obj_num = eid.split(" ")[1]
                if (t, obj_num) in motion_log_data:
                    log_s = motion_log_data[(t, obj_num)]
                    s['x'] = log_s['x']
                    s['y'] = log_s['y']
                    s['vx'] = log_s['vx']
                    s['vy'] = log_s['vy']

        # Motion update
        for eid, s in state.items():
            if s['exists']:
                s['x'] += s['vx'] * dt
                s['y'] += s['vy'] * dt

        # Collision detection and resolution
        active_eids = [eid for eid, s in state.items() if s['exists']]
        for i in range(len(active_eids)):
            for j in range(i + 1, len(active_eids)):
                eid1, eid2 = active_eids[i], active_eids[j]
                p1 = np.array([state[eid1]['x'], state[eid1]['y']])
                p2 = np.array([state[eid2]['x'], state[eid2]['y']])
                dist = np.linalg.norm(p1 - p2)

                if dist < collision_threshold:
                    pair = tuple(sorted([eid1, eid2]))
                    if last_collision_time.get(pair, -100) < t - 2.0:
                        v1 = np.array([state[eid1]['vx'], state[eid1]['vy']])
                        v2 = np.array([state[eid2]['vx'], state[eid2]['vy']])
                        n = p1 - p2
                        n_len = np.linalg.norm(n)
                        if n_len > 0:
                            n /= n_len
                            v_rel = v1 - v2
                            v_rel_n = np.dot(v_rel, n)
                            if v_rel_n < 0:  # Approach check
                                dv = v_rel_n * n
                                state[eid1]['vx'] -= dv[0]
                                state[eid1]['vy'] -= dv[1]
                                state[eid2]['vx'] += dv[0]
                                state[eid2]['vy'] += dv[1]
                                last_collision_time[pair] = t
                                if t > start:
                                    outcomes_found.append({
                                        "time": float(round(t)),
                                        "kind": "collision",
                                        "entities": [eid1, eid2],
                                        "value": None,
                                        "src": None
                                    })

        # Exit detection
        for eid in active_eids:
            s = state[eid]
            if abs(s['x']) > exit_threshold or abs(s['y']) > exit_threshold:
                s['exists'] = False
                if t > start:
                    outcomes_found.append({
                        "time": float(round(t)),
                        "kind": "exit",
                        "entities": [eid],
                        "value": None,
                        "src": None
                    })

        t += dt

    return outcomes_found

