import numpy as np

def simulate(doc, scope, inputs, params, start=None, horizon=None) -> list:
    """
    A forward model of the physics process recorded in the scope.

    Key insight from data investigation: The velocities (vx, vy) recorded in the 
    motion log (and subsequently provided in inputs) are given as displacement 
    per 10 frames, not per frame or per second. Therefore, the position update
    is: x = x + (vx / 10) * frames.
    """
    # 1. Time boundaries
    # recorded_end(doc, scope) is a provided helper
    rec_end_val = recorded_end(doc, scope)
    if horizon is None:
        horizon = rec_end_val if rec_end_val is not None else 127.0
    if start is None:
        start = 0.0

    # 2. State initialization
    # state[eid] stores physics properties: position, velocity, and existence.
    state = {}  # eid -> {'x', 'y', 'vx', 'vy', 'exists': True}
    sorted_inputs = sorted(inputs, key=lambda x: x["time"])
    outcomes_found = []

    t = 0.0
    input_idx = 0
    dt = 1.0  # Simulation step of 1 frame

    # Collision threshold derived from analyzed distances (typically 0.6 to 1.5).
    collision_threshold = 1.5

    # Exit threshold based on observed boundary coordinates (approx +/- 15).
    exit_threshold = 15.0

    # Cooldown to prevent the same pair from colliding every frame (sticking)
    last_collision_time = {}  # (eid1, eid2) -> time

    # 3. Simulation Loop
    while t <= horizon:
        # Process arrival events: add objects to the scene
        while input_idx < len(sorted_inputs) and sorted_inputs[input_idx]["time"] <= t:
            inp = sorted_inputs[input_idx]
            for eid in inp["entities"]:
                f = inp["fields"]
                state[eid] = {
                    'x': f.get('x', 0.0),
                    'y': f.get('y', 0.0),
                    'vx': f.get('vx', 0.0),
                    'vy': f.get('vy', 0.0),
                    'exists': True
                }
            input_idx += 1

        # Position update: Apply the (vx/10) rule for movement per frame
        for eid, s in state.items():
            if s['exists']:
                s['x'] += (s['vx'] / 10.0) * dt
                s['y'] += (s['vy'] / 10.0) * dt

        # Collision check: Apply equal-mass elastic collision logic
        active_eids = [eid for eid, s in state.items() if s['exists']]
        for i in range(len(active_eids)):
            for j in range(i + 1, len(active_eids)):
                eid1, eid2 = active_eids[i], active_eids[j]
                p1 = np.array([state[eid1]['x'], state[eid1]['y']])
                p2 = np.array([state[eid2]['x'], state[eid2]['y']])

                dist = np.linalg.norm(p1 - p2)
                if dist < collision_threshold:
                    pair = tuple(sorted([eid1, eid2]))
                    # cooldown window of 2 frames
                    if last_collision_time.get(pair, -100) < t - 2.0:
                        v1 = np.array([state[eid1]['vx'], state[eid1]['vy']])
                        v2 = np.array([state[eid2]['vx'], state[eid2]['vy']])
                        n = p1 - p2
                        n_len = np.linalg.norm(n)
                        if n_len > 0:
                            n = n / n_len
                            v_rel = v1 - v2
                            v_rel_n = np.dot(v_rel, n)

                            # Only resolve collision if objects are moving toward each other
                            if v_rel_n < 0:
                                # Elastic collision formula for equal masses:
                                # Change in velocity is the projection of relative velocity on normal
                                dv = v_rel_n * n
                                state[eid1]['vx'] -= dv[0]
                                state[eid1]['vy'] -= dv[1]
                                state[eid2]['vx'] += dv[0]
                                state[eid2]['vy'] += dv[1]
                                last_collision_time[pair] = t

                                if t > start:
                                    outcomes_found.append({
                                        "time": float(round(t)),
                                        "kind": "collision",
                                        "entities": [eid1, eid2],
                                        "value": None,
                                        "src": None
                                    })

        # Exit check: remove objects that move outside the scene boundary
        for eid in active_eids:
            s = state[eid]
            if abs(s['x']) > exit_threshold or abs(s['y']) > exit_threshold:
                s['exists'] = False
                if t > start:
                    outcomes_found.append({
                        "time": float(round(t)),
                        "kind": "exit",
                        "entities": [eid],
                        "value": None,
                        "src": None
                    })

        t += dt

    return outcomes_found

