import numpy as np

def simulate(doc, scope, inputs, params, start=None, horizon=None) -> list:
    """
    A forward model of the process recorded in the scope.
    """
    # Parameters
    stationary_threshold = params.get("stationary_threshold", 0.1)

    # Determine the simulation time range
    rec_end = recorded_end(doc, scope)
    if horizon is None:
        horizon = rec_end
    if start is None:
        start = 0.0

    # Active entities are those that have at least one input
    active_entities = set()
    for inp in inputs:
        active_entities.update(inp["entities"])

    # State storage: { entity_id: { 'x', 'y', 'vx', 'vy', 'active' } }
    state = {}

    # We need the motion log to get the latest state at or before 'start'
    log_node = node_by_title(doc, f"{scope}: Motion log")
    log_rows = table_rows(log_node) if log_node else []

    def get_log_state(eid, t):
        # Objects in log are named "0 green rubber cube", eids are "Object 0"
        obj_num = eid.split(" ")[1]
        best_row = None
        for _, row in log_rows:
            f = float(row["frame"])
            if f <= t and row["object"].startswith(obj_num + " "):
                if best_row is None or f > float(best_row["frame"]):
                    best_row = row
        return best_row

    # Initial state at 'start'
    # 1. Find arrival times for all active entities
    arrival_map = {}
    for inp in inputs:
        if inp["kind"] == "arrival":
            for eid in inp["entities"]:
                arrival_map[eid] = inp

    for eid in active_entities:
        # Check if the entity has arrived by 'start'
        arr = arrival_map.get(eid)
        if arr and arr["time"] <= start:
            # Try to find the latest recorded state at or before 'start'
            log_s = get_log_state(eid, start)
            if log_s:
                state[eid] = {
                    "x": float(log_s["x"]),
                    "y": float(log_s["y"]),
                    "vx": float(log_s["vx"]),
                    "vy": float(log_s["vy"]),
                    "active": True
                }
            else:
                # Rebuild from arrival if no log record exists
                t_arr = arr["time"]
                fields = arr["fields"]
                dt = start - t_arr
                state[eid] = {
                    "x": fields.get("x", 0.0) + fields.get("vx", 0.0) * dt,
                    "y": fields.get("y", 0.0) + fields.get("vy", 0.0) * dt,
                    "vx": fields.get("vx", 0.0),
                    "vy": fields.get("vy", 0.0),
                    "active": True
                }
        else:
            state[eid] = {"active": False}

    # Simulation loop
    outcomes_found = []

    # We simulate frame by frame as the motion log and outcomes are indexed by frames
    t = start
    while t < horizon:
        t += 1.0

        # 1. Process Arrivals at time t
        for inp in inputs:
            if inp["kind"] == "arrival" and inp["time"] == t:
                for eid in inp["entities"]:
                    f = inp["fields"]
                    state[eid] = {
                        "x": f.get("x", 0.0),
                        "y": f.get("y", 0.0),
                        "vx": f.get("vx", 0.0),
                        "vy": f.get("vy", 0.0),
                        "active": True
                    }

        # 2. Update Positions (assuming constant velocity between collisions)
        for eid, s in state.items():
            if s.get("active"):
                s["x"] += s["vx"]
                s["y"] += s["vy"]

        # 3. Check for Collisions
        # We use a distance threshold based on explored data (~0.4-0.5)
        collision_dist = 0.45
        active_objs = [eid for eid in state if state[eid].get("active")]

        # We use a set to avoid multiple collisions for the same pair in one frame
        processed_pairs = set()

        for i in range(len(active_objs)):
            for j in range(i + 1, len(active_objs)):
                e1, e2 = active_objs[i], active_objs[j]
                pair = tuple(sorted([e1, e2]))
                if pair in processed_pairs:
                    continue

                p1 = np.array([state[e1]["x"], state[e1]["y"]])
                p2 = np.array([state[e2]["x"], state[e2]["y"]])
                dist = np.linalg.norm(p1 - p2)

                if dist <= collision_dist:
                    v1 = np.array([state[e1]["vx"], state[e1]["vy"]])
                    v2 = np.array([state[e2]["vx"], state[e2]["vy"]])

                    # Elastic collision model for equal masses
                    diff_v = v1 - v2
                    diff_p = p1 - p2
                    p_sq = np.dot(diff_p, diff_p)
                    if p_sq > 1e-9:
                        proj = np.dot(diff_v, diff_p) / p_sq
                        v1_new = v1 - proj * diff_p
                        v2_new = v2 + proj * diff_p

                        state[e1]["vx"], state[e1]["vy"] = v1_new
                        state[e2]["vx"], state[e2]["vy"] = v2_new

                    outcomes_found.append({
                        "time": t,
                        "kind": "collision",
                        "entities": [e1, e2],
                        "value": None,
                        "src": []
                    })
                    processed_pairs.add(pair)

        # 4. Check for Exits
        # Common boundary in CLEVRER is roughly distance 10 from center
        exit_boundary = 10.0
        for eid in active_objs:
            p = np.array([state[eid]["x"], state[eid]["y"]])
            if np.linalg.norm(p) > exit_boundary:
                state[eid]["active"] = False
                outcomes_found.append({
                    "time": t,
                    "kind": "exit",
                    "entities": [eid],
                    "value": None,
                    "src": []
                })

    return outcomes_found

