        obj_num = eid.split(" ")[1]
        best_row = None
        for _, row in log_rows:
            f = float(row["frame"])
            if f <= t and row["object"].startswith(obj_num + " "):
                if best_row is None or f > float(best_row["frame"]):
                    best_row = row
        return best_row

