    arrival_map = {}
    for inp in inputs:
        if inp["kind"] == "arrival":
            for eid in inp["entities"]:
                arrival_map[eid] = inp

    for eid in active_entities:
        arr = arrival_map.get(eid)
        if arr and arr["time"] <= start:
            log_s = get_log_state(eid, start)
            if log_s:
                state[eid] = {
                    "x": float(log_s["x"]),
                    "y": float(log_s["y"]),
                    "vx": float(log_s["vx"]),
                    "vy": float(log_s["vy"]),
                    "active": True
                }
            else:
                t_arr = arr["time"]
                fields = arr["fields"]
                dt = start - t_arr
                state[eid] = {
                    "x": fields.get("x", 0.0) + fields.get("vx", 0.0) * dt,
                    "y": fields.get("y", 0.0) + fields.get("vy", 0.0) * dt,
                    "vx": fields.get("vx", 0.0),
                    "vy": fields.get("vy", 0.0),
                    "active": True
                }
        else:
            state[eid] = {"active": False}

    outcomes_found = []

    # The simulation must check for outcomes at integer frame boundaries.
    # Start by moving from 'start' to the next integer frame.
    t_current = start
    t_next = np.ceil(start)
    if t_next == start:
        t_next += 1.0

    while t_current < horizon:
        dt = t_next - t_current

        # 1. Update Positions
        for eid, s in state.items():
            if s.get("active"):
                s["x"] += s["vx"] * dt
                s["y"] += s["vy"] * dt

        t_current = t_next
        if t_current > horizon:
            break

        # 2. Process Arrivals at this integer frame
        for inp in inputs:
            if inp["kind"] == "arrival" and float(inp["time"]) == t_current:
                for eid in inp["entities"]:
                    f = inp["fields"]
                    state[eid] = {
                        "x": f.get("x", 0.0),
                        "y": f.get("y", 0.0),
                        "vx": f.get("vx", 0.0),
                        "vy": f.get("vy", 0.0),
                        "active": True
                    }

        # 3. Check for Collisions at this integer frame
        collision_dist = 0.5  # Slightly larger to capture collisions
        active_objs = [eid for eid in state if state[eid].get("active")]

        # Collision resolution (simplified)
        for i in range(len(active_objs)):
            for j in range(i + 1, len(active_objs)):
                e1, e2 = active_objs[i], active_objs[j]
                p1 = np.array([state[e1]["x"], state[e1]["y"]])
                p2 = np.array([state[e2]["x"], state[e2]["y"]])
                dist = np.linalg.norm(p1 - p2)

                if dist <= collision_dist:
                    v1 = np.array([state[e1]["vx"], state[e1]["vy"]])
                    v2 = np.array([state[e2]["vx"], state[e2]["vy"]])

                    # Elastic collision model for equal masses
                    diff_v = v1 - v2
                    diff_p = p1 - p2
                    p_sq = np.dot(diff_p, diff_p)
                    if p_sq > 1e-9:
                        proj = np.dot(diff_v, diff_p) / p_sq
                        # Only collide if moving towards each other
                        if proj > 0:
                            v1_new = v1 - proj * diff_p
                            v2_new = v2 + proj * diff_p
                            state[e1]["vx"], state[e1]["vy"] = v1_new
                            state[e2]["vx"], state[e2]["vy"] = v2_new

                    outcomes_found.append({
                        "time": float(t_current),
                        "kind": "collision",
                        "entities": [e1, e2],
                        "value": None,
                        "src": []
                    })

        # 4. Check for Exits at this integer frame
        # Using a much larger boundary to avoid extra exits
        exit_boundary = 20.0
        for eid in active_objs:
            p = np.array([state[eid]["x"], state[eid]["y"]])
            if np.linalg.norm(p) > exit_boundary:
                state[eid]["active"] = False
                outcomes_found.append({
                    "time": float(t_current),
                    "kind": "exit",
                    "entities": [eid],
                    "value": None,
                    "src": []
                })

        t_next += 1.0

    return outcomes_found

