                            state[e1]["vx"], state[e1]["vy"] = v1_new
                            state[e2]["vx"], state[e2]["vy"] = v2_new

                    outcomes_found.append({
                        "time": float(t_current),
                        "kind": "collision",
                        "entities": [e1, e2],
                        "value": None,
                        "src": []
                    })
