                dist = np.linalg.norm(p1 - p2)

                if dist <= collision_dist:
                    # Use the log velocities for collision physics, but scale them
                    v1 = np.array([state[e1]["vx"], state[e1]["vy"]]) * scaling_factor
                    v2 = np.array([state[e2]["vx"], state[e2]["vy"]]) * scaling_factor

                    diff_v = v1 - v2
                    diff_p = p1 - p2
                    p_sq = np.dot(diff_p, diff_p)
                    if p_sq > 1e-9:
                        proj = np.dot(diff_v, diff_p) / p_sq
                        if proj > 0:
                            v1_new = v1 - proj * diff_p
                            v2_new = v2 + proj * diff_p
                            # Store back the unscaled log-velocities
                            state[e1]["vx"], state[e1]["vy"] = v1_new / scaling_factor
                            state[e2]["vx"], state[e2]["vy"] = v2_new / scaling_factor

                    outcomes_found.append({
                        "time": float(t_current),
                        "kind": "collision",
                        "entities": [e1, e2],
                        "value": None,
                        "src": []
                    })
                    processed_pairs.add(pair)

        # 4. Check for Exits at this integer frame
        # Bound check: based on CLEVRER typical boundaries
        exit_boundary = 12.0
        for eid in active_objs:
            p = np.array([state[eid]["x"], state[eid]["y"]])
            if np.linalg.norm(p) > exit_boundary:
                state[eid]["active"] = False
                outcomes_found.append({
                    "time": float(t_current),
                    "kind": "exit",
                    "entities": [eid],
                    "value": None,
                    "src": []
                })

        t_next += 1.0

    return outcomes_found

