import numpy as np

def simulate(doc, scope, inputs, params, start=None, horizon=None) -> list:
    """
    A forward model of the process recorded in the scope.
    """
    # Constants from simulation environment
    # 128 frames is about 5 seconds, so delta_t per frame is 5/128
    DT = 5.0 / 128.0

    # Determine the simulation time range
    rec_end = recorded_end(doc, scope)
    if horizon is None:
        horizon = rec_end
    if start is None:
        start = 0.0

    # Active entities are those that have at least one input
    active_entities = set()
    for inp in inputs:
        active_entities.update(inp["entities"])

    # State storage: { entity_id: { 'x', 'y', 'vx', 'vy', 'active' } }
    state = {}

    # We need the motion log to get the latest state at or before 'start'
    log_node = node_by_title(doc, f"{scope}: Motion log")
    log_rows = table_rows(log_node) if log_node else []

    def get_log_state(eid, t):
        # Objects in log are named "0 green rubber cube", eids are "Object 0"
        obj_num = eid.split(" ")[1]
        best_row = None
        for _, row in log_rows:
            f = float(row["frame"])
            if f <= t and row["object"].startswith(obj_num + " "):
                if best_row is None or f > float(best_row["frame"]):
                    best_row = row
        return best_row

    # Initial state at 'start'
    arrival_map = {}
    for inp in inputs:
        if inp["kind"] == "arrival":
            for eid in inp["entities"]:
                arrival_map[eid] = inp

    for eid in active_entities:
        arr = arrival_map.get(eid)
        if arr and arr["time"] <= start:
            log_s = get_log_state(eid, start)
            if log_s:
                state[eid] = {
                    "x": float(log_s["x"]),
                    "y": float(log_s["y"]),
                    "vx": float(log_s["vx"]),
                    "vy": float(log_s["vy"]),
                    "active": True
                }
            else:
                t_arr = arr["time"]
                fields = arr["fields"]
                # Extrapolate from arrival to start using the DT scale
                dt_frames = start - t_arr
                state[eid] = {
                    "x": fields.get("x", 0.0) + fields.get("vx", 0.0) * dt_frames * DT,
                    "y": fields.get("y", 0.0) + fields.get("vy", 0.0) * dt_frames * DT,
                    "vx": fields.get("vx", 0.0),
                    "vy": fields.get("vy", 0.0),
                    "active": True
                }
        else:
            state[eid] = {"active": False}

    outcomes_found = []

    # Track collision cooldowns to prevent "sticking"
    # pair -> frame_of_last_collision
    collision_cooldown = {}

    # Simulation timing: Sync to integer frames
    t_current = start
    t_next = np.ceil(start)
    if t_next == start:
        t_next += 1.0

    while t_current < horizon:
        dt_frames = t_next - t_current

        # 1. Update Positions
        for eid, s in state.items():
            if s.get("active"):
                s["x"] += s["vx"] * dt_frames * DT
                s["y"] += s["vy"] * dt_frames * DT

        t_current = t_next
        if t_current > horizon:
            break

        # 2. Process Arrivals at this integer frame
        for inp in inputs:
            if inp["kind"] == "arrival" and float(inp["time"]) == t_current:
                for eid in inp["entities"]:
                    f = inp["fields"]
                    state[eid] = {
                        "x": f.get("x", 0.0),
                        "y": f.get("y", 0.0),
                        "vx": f.get("vx", 0.0),
                        "vy": f.get("vy", 0.0),
                        "active": True
                    }

        # 3. Check for Collisions at this integer frame
        collision_dist = 0.45
        active_objs = [eid for eid in state if state[eid].get("active")]

        processed_pairs = set()
        for i in range(len(active_objs)):
            for j in range(i + 1, len(active_objs)):
                e1, e2 = active_objs[i], active_objs[j]
                pair = tuple(sorted([e1, e2]))
                if pair in processed_pairs:
                    continue

                # Cooldown check: wait 2 frames before colliding again
                if pair in collision_cooldown and t_current - collision_cooldown[pair] < 2:
                    continue

                p1 = np.array([state[e1]["x"], state[e1]["y"]])
                p2 = np.array([state[e2]["x"], state[e2]["y"]])
                dist = np.linalg.norm(p1 - p2)

                if dist <= collision_dist:
                    v1 = np.array([state[e1]["vx"], state[e1]["vy"]])
                    v2 = np.array([state[e2]["vx"], state[e2]["vy"]])

                    diff_v = v1 - v2
                    diff_p = p1 - p2
                    p_sq = np.dot(diff_p, diff_p)
                    if p_sq > 1e-9:
                        # Normal projection of relative velocity onto relative position
                        # proj > 0 means they are moving towards each other
                        proj = np.dot(diff_v, diff_p) / p_sq
                        if proj > 0:
                            # Simple elastic collision for equal masses
                            v1_new = v1 - proj * diff_p
                            v2_new = v2 + proj * diff_p
                            state[e1]["vx"], state[e1]["vy"] = v1_new
                            state[e2]["vx"], state[e2]["vy"] = v2_new

                    outcomes_found.append({
                        "time": float(t_current),
                        "kind": "collision",
                        "entities": [e1, e2],
                        "value": None,
                        "src": []
                    })
                    collision_cooldown[pair] = t_current
                    processed_pairs.add(pair)

        # 4. Check for Exits at this integer frame
        # Conservative boundary to avoid false positives
        exit_boundary = 15.0
        for eid in active_objs:
            p = np.array([state[eid]["x"], state[eid]["y"]])
            if np.linalg.norm(p) > exit_boundary:
                state[eid]["active"] = False
                outcomes_found.append({
                    "time": float(t_current),
                    "kind": "exit",
                    "entities": [eid],
                    "value": None,
                    "src": []
                })

        t_next += 1.0

    return outcomes_found

