def analyze_velocity_scale(doc, scope):
    motion = get_motion_data(doc, scope)
    scales = []
    for obj_id, frames in motion.items():
        sorted_f = sorted(frames.keys())
        for i in range(len(sorted_f) - 1):
            f1, f2 = sorted_f[i], sorted_f[i+1]
            dt = f2 - f1
            s1, s2 = frames[f1], frames[f2]
            dx = s2["x"] - s1["x"]
            if abs(s1["vx"]) > 0.1:
                scales.append(dx / (s1["vx"] * dt))
    if scales:
        print(f"{scope} Scale: mean={np.mean(scales):.4f}, median={np.median(scales):.4f}")

