def analyze_collision_frames(doc, scope):
    motion = get_motion_data(doc, scope)
    events = outcomes(doc, scope)
    for e in events:
        if e["kind"] == "collision":
            t = int(e["time"])
            eids = e["entities"]
            if len(eids) != 2: continue
            id1, id2 = eids
            if id1 not in motion or id2 not in motion: continue

            # Distance at t-1 and t
            def get_dist(frame):
                if frame not in motion[id1] or frame not in motion[id2]:
                    return None
                s1 = motion[id1][frame]
                s2 = motion[id2][frame]
                return np.sqrt((s1["x"] - s2["x"])**2 + (s1["y"] - s2["y"])**2)

            d_prev = get_dist(t - 1)
            d_curr = get_dist(t)
            print(f"{scope} Collision at {t}: dist({t-1})={d_prev}, dist({t})={d_curr}")

